void reset_sos(void)
{
    settingssos_state_param_t sos_state;
    s32             ret;

    sos_state.state     = 0;
    ret                 = aic_md_write(MD_ID_SETTING_SOS_ENABLE,sizeof(settingssos_state_param_t),&sos_state);

    if (ret) {
        APP_LOGI("reset_sos read net cfg error 0x%x\n",ret);
        }

    settingssos_number_param_t sos_number;

    for (uint8_t j = 0; j < 3; j++) {
        for (uint8_t i = 0; i < 16; i++) {
            sos_number.number_for_sos[j][i] = 0;
            }
        }

    ret                 = aic_md_write(MD_ID_SETTING_SOS_NUMBER,sizeof(settingssos_number_param_t),&sos_number);

    if (ret) {
        APP_LOGI("reset_sos read net cfg error 0x%x\n",ret);
        }
}



uint8_t get_sos_status(void)
{
    settingssos_state_param_t sos_state;
    s32             ret;

    ret                 = aic_md_read(MD_ID_SETTING_SOS_ENABLE,sizeof(settingssos_state_param_t),&sos_state);

    if (ret) {
        APP_LOGI("reset_sos read net cfg error 0x%x\n",ret);
        }

    if (sos_state.state == 0)
        return 0;

    settingssos_number_param_t sos_number;
    uint8_t         j   = 0;

    ret                 = aic_md_read(MD_ID_SETTING_SOS_NUMBER,sizeof(settingssos_number_param_t),&sos_number);

    if (ret) {
        APP_LOGI("reset_sos read net cfg error 0x%x\n",ret);
        }

    for (j = 0; j < 3; j++) {
        if (sos_number.number_for_sos[j][0] != 0)
            break;
        }

    if (j >= 3)
        return 0;

    return 1;
}

void sos_send_sms(void)
{
    settingssos_number_param_t sos_number;
    uint8_t         j   = 0;
    s32             ret;

    ret                 = aic_md_read(MD_ID_SETTING_SOS_NUMBER,sizeof(settingssos_number_param_t),&sos_number);

    if (ret) {
        APP_LOGI("reset_sos read net cfg error 0x%x\n",ret);
        }

    for (j = 0; j < 3; j++) {
        if (sos_number.number_for_sos[j][0] == 0)
            continue;

        tele_sms_data_set_send_fun_callback(NULL,NULL);
        tele_sms_data_send("我需要您的帮助",sos_number.number_for_sos[j],NULL,false);

        //__inf("aaa = 我需要您的帮助,number = %s\r\n",sos_number.number_for_sos[j]);
        aic_mdelay(200);

        //tele_sms_data_send("我需要您的帮助", "13316950937",NULL, false);
        }

}

uint8_t get_sos_number(uint8_t number,char * buffer)
{
    settingssos_number_param_t sos_number;
    s32             ret;

    if (number >= 3)
        return 0;

    ret                 = aic_md_read(MD_ID_SETTING_SOS_NUMBER,sizeof(settingssos_number_param_t),&sos_number);

    if (ret) {
        APP_LOGI("reset_sos read net cfg error 0x%x\n",ret);
        }

    //__inf("mmm = get_sos_number = %s,[0]=%d,number=%d\r\n",sos_number.number_for_sos[number],sos_number.number_for_sos[number][0],number);
    if (sos_number.number_for_sos[number][0] == 0) {
        return 0;
        }
    else 
        strncpy(buffer,sos_number.number_for_sos[number],16);

    return 1;
}

